.container {
    font-family: 'Segoe UI', sans-serif;
    max-width: 600px;
    margin: 0 auto;
    padding: 20px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border-radius: 20px;
    color: white;
}

h2 {
    text-align: center;
    margin-bottom: 10px;
}

.instruction {
    text-align: center;
    opacity: 0.9;
    margin-bottom: 20px;
}

.experiment-area {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 30px;
    padding: 30px;
    background: rgba(255,255,255,0.1);
    border-radius: 15px;
    min-height: 200px;
}

.magnet {
    width: 60px;
    height: 120px;
    background: linear-gradient(180deg, #ff6b6b 50%, #4ecdc4 50%);
    border-radius: 10px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    cursor: grab;
    user-select: none;
    box-shadow: 0 4px 15px rgba(0,0,0,0.3);
    transition: transform 0.1s;
}

.magnet:active {
    cursor: grabbing;
}

.magnet-n, .magnet-s {
    font-weight: bold;
    font-size: 18px;
    color: white;
    text-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

.coil-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 15px;
}

.coil {
    width: 100px;
    height: 100px;
    border: 8px solid #ffd93d;
    border-radius: 50%;
    position: relative;
    background: rgba(255,255,255,0.1);
}

.coil::before {
    content: '';
    position: absolute;
    top: 50%;
    left: -20px;
    width: 20px;
    height: 4px;
    background: #ffd93d;
}

.coil::after {
    content: '';
    position: absolute;
    top: 50%;
    right: -20px;
    width: 20px;
    height: 4px;
    background: #ffd93d;
}

.ammeter {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
}

.meter-display {
    font-size: 24px;
    font-weight: bold;
    font-family: monospace;
    background: #1a1a2e;
    padding: 5px 15px;
    border-radius: 5px;
    color: #00ff00;
}

.meter-label {
    font-size: 12px;
    opacity: 0.8;
}

.direction-indicator {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
    padding: 15px;
    background: rgba(255,255,255,0.1);
    border-radius: 10px;
}

.direction-label {
    font-size: 12px;
    opacity: 0.8;
}

.direction-value {
    font-size: 16px;
    font-weight: bold;
}

.status-panel {
    display: flex;
    justify-content: space-around;
    margin-top: 20px;
    padding: 15px;
    background: rgba(255,255,255,0.1);
    border-radius: 10px;
}

.status-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
}

.status-label {
    font-size: 12px;
    opacity: 0.8;
}

.status-value {
    font-size: 18px;
    font-weight: bold;
}

.principle-box {
    margin-top: 20px;
    padding: 15px;
    background: rgba(255,255,255,0.15);
    border-radius: 10px;
    text-align: center;
}

.principle-box h4 {
    margin: 0 0 10px 0;
}

.principle-box p {
    margin: 0;
    font-size: 14px;
    line-height: 1.5;
}

