const magnet = document.getElementById('magnet');
const coil = document.getElementById('coil');
const meterDisplay = document.getElementById('meterDisplay');
const directionValue = document.getElementById('directionValue');
const fluxChange = document.getElementById('fluxChange');
const emfValue = document.getElementById('emfValue');
const principleText = document.getElementById('principleText');

let isDragging = false;
let startY = 0;
let magnetY = 0;
let currentEMF = 0;
let velocity = 0;
let lastMagnetY = 0;
let animationId = null;

// 拖动磁铁
magnet.addEventListener('mousedown', (e) => {
    isDragging = true;
    startY = e.clientY - magnetY;
    magnet.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;

    magnetY = e.clientY - startY;
    // 限制移动范围
    magnetY = Math.max(-100, Math.min(100, magnetY));
    magnet.style.transform = `translateY(${magnetY}px)`;

    // 计算速度（用于计算感应电动势）
    velocity = magnetY - lastMagnetY;
    lastMagnetY = magnetY;

    updateExperiment();
});

document.addEventListener('mouseup', () => {
    if (isDragging) {
        isDragging = false;
        magnet.style.cursor = 'grab';
        velocity = 0;
        updateExperiment();
    }
});

function updateExperiment() {
    // 根据磁铁位置和速度计算感应电动势
    // E = B * L * v (简化模型)
    const B = 0.5; // 磁感应强度
    const L = 0.1; // 线圈等效长度
    const baseEMF = Math.abs(velocity) * B * L * 50; // 缩放因子

    // 添加一些惯性效果
    currentEMF = currentEMF * 0.8 + baseEMF * 0.2;

    // 更新显示
    meterDisplay.textContent = currentEMF.toFixed(2);
    emfValue.textContent = (currentEMF * 10).toFixed(2) + ' V';

    // 判断电流方向
    if (Math.abs(currentEMF) < 0.1) {
        directionValue.textContent = '无电流';
        directionValue.style.color = '#aaa';
        fluxChange.textContent = '不变';
        principleText.textContent = '磁铁静止时，磁通量不变，没有感应电流！';
    } else if (velocity > 0) {
        // 向下移动（N极靠近线圈）
        directionValue.textContent = '逆时针 ↑';
        directionValue.style.color = '#ff6b6b';
        fluxChange.textContent = '增加 ↑';
        principleText.textContent = 'N极靠近 → 磁通量增加 → 感应电流产生反向磁场（楞次定律：增反减同）';
    } else if (velocity < 0) {
        // 向上移动（N极远离线圈）
        directionValue.textContent = '顺时针 ↓';
        directionValue.style.color = '#4ecdc4';
        fluxChange.textContent = '减少 ↓';
        principleText.textContent = 'N极远离 → 磁通量减少 → 感应电流产生同向磁场补偿（楞次定律：增反减同）';
    }

    // 发送结果到系统
    window.HeurisStage.emit('experiment-result', {
        magnetPosition: magnetY,
        velocity: velocity,
        emf: currentEMF * 10,
        current: currentEMF,
        direction: Math.abs(currentEMF) < 0.1 ? 'none' : (velocity > 0 ? 'counterclockwise' : 'clockwise'),
        fluxChange: Math.abs(currentEMF) < 0.1 ? 'constant' : (velocity > 0 ? 'increasing' : 'decreasing'),
        knowledgePoint: '电磁感应 / 楞次定律'
    });
}

// 缓慢衰减效果
function decay() {
    if (!isDragging) {
        currentEMF *= 0.95;
        meterDisplay.textContent = currentEMF.toFixed(2);
        emfValue.textContent = (currentEMF * 10).toFixed(2) + ' V';

        if (currentEMF < 0.01) {
            directionValue.textContent = '无电流';
            directionValue.style.color = '#aaa';
            fluxChange.textContent = '不变';
            principleText.textContent = '磁铁静止时，磁通量不变，没有感应电流！';
        }
    }
    requestAnimationFrame(decay);
}
decay();

// 初始提示
window.HeurisStage.emit('experiment-result', {
    type: 'init',
    message: '拖动磁铁开始实验',
    knowledgePoint: '电磁感应 / 楞次定律'
});

